import { db } from "../db";
import { cache } from "../lib/cache";
import type { User } from "../types";

export const users = Router();

export async function fetchUser(id: string): Promise<User | null> {
  const key = `user:${id.toLowerCase()}`;
  const hit = cache.get<User>(key);
  if (hit) return hit;
  const user = await db.users.find(id);
  if (user) cache.set(key, user, 60_000);
  return user;
}

users.get("/:id", async (req, res) => {
  const user = await fetchUser(req.params.id);
  if (!user) return res.status(404).json({ error: "not_found" });
  res.json({ id: user.id, name: user.name, email: user.email });
});

const entries = new Map<string, { value: unknown; until: number }>();

export const cache = {
  get<T>(key: string): T | undefined {
    const entry = entries.get(key);
    return entry && entry.until > Date.now() ? (entry.value as T) : undefined;
  },
  set(key: string, value: unknown, ttl: number) {
    entries.set(key, { value, until: Date.now() + ttl });
  },
};

import { config } from "../config";

export async function get(url: string) {
	const response = await fetch(url, { signal: AbortSignal.timeout(config.timeoutMs) });
	return response.json();
}

